<?phpclass Breadcrumb {	public static function get_breadcrumb(): void    {        echo '<a href="' . home_url() . '" rel="nofollow"><i class="bi bi-house me-1"></i>خانه</a>';        if (is_single()) {            echo '&nbsp;&#187;&nbsp';            $category_id = get_post_meta(get_the_ID(), '_ta_post_cat', true);            if ($category_id) {                $category_link = get_category_link($category_id);                $category_name = get_cat_name($category_id); // بهتر است از get_cat_name استفاده کنید                if ($category_link && $category_name) {                    echo '<li><a href="' . esc_url($category_link) . '">' . esc_html($category_name) . '</a></li>';                }            }            if (is_single()) {                echo '&nbsp;&#187;&nbsp';                the_title('<li>', '</li>', true);            }        }        if (is_page()) {            echo '&nbsp;&#187;&nbsp';            the_title('<li>', '</li>', true);        }        if (is_search()) {            echo '&nbsp;&#187;&nbsp';            echo '<em>';            echo get_search_query();            echo '</em>';        }        if ( is_category() ) {            echo '&nbsp;&#187;&nbsp';            $category = get_queried_object(); // دریافت دسته‌بندی فعلی            if ( $category ) {                $category_link = get_category_link( $category->term_id );                $category_name = $category->name;                if ( $category_link && $category_name ) {                    echo '<li class="breadcrumb-item"><a href="' . esc_url( $category_link ) . '">' . esc_html( $category_name ) . '</a></li>';                }            }        }        if (is_tag()) {            echo '&nbsp;&#187;&nbsp';            echo '<li><a href="#">' . esc_html(single_tag_title()) . '</a></li>';        }        if (is_archive()) {            echo '&nbsp;&#187;&nbsp';            if (is_year()) {                echo get_the_time('آرشیو سال Y');            } elseif (is_month()) {                echo get_the_date();            } elseif (is_day()) {                echo get_the_date();            }        }    }}